/**
 * Platform icons and splash (generated by `npm run icons:build` from the SKOR
 * SPOR mark): right sizes, opaque where the store requires it, transparent
 * where the platform composes them, and wired into app.json and the web page.
 * Never the Expo template images again.
 */
import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

import { expect, test } from '@playwright/test';

const ROOT = join(__dirname, '../..');

/** PNG header: width, height and color type (2 = RGB, 6 = RGBA). */
function png(file: string) {
  const b = readFileSync(join(ROOT, file));
  expect(b.subarray(1, 4).toString('latin1'), `${file} is a PNG`).toBe('PNG');
  return { width: b.readUInt32BE(16), height: b.readUInt32BE(20), colorType: b[25], sha: createHash('sha256').update(b).digest('hex') };
}

// SHA-256 of the Expo template images the project started with (initial commit).
const EXPO_TEMPLATE_FAVICON_48 = { width: 48, height: 48 };

test.describe('Marka varlıkları', () => {
  test('iOS ikonları 1024×1024 ve opak (App Store şeffaf piksel kabul etmez)', () => {
    for (const f of ['assets/icon.png', 'assets/icon-dark.png', 'assets/icon-tinted.png']) {
      const p = png(f);
      expect([p.width, p.height], f).toEqual([1024, 1024]);
      expect(p.colorType, `${f} must have no alpha channel`).toBe(2);
    }
  });

  test('Android uyarlanabilir ikon: ön plan ve tek renk şeffaf, arka plan opak; hepsi aynı boyutta', () => {
    const fg = png('assets/android-icon-foreground.png');
    const bg = png('assets/android-icon-background.png');
    const mono = png('assets/android-icon-monochrome.png');
    for (const p of [fg, bg, mono]) expect([p.width, p.height]).toEqual([1024, 1024]);
    expect(fg.colorType).toBe(6);
    expect(mono.colorType).toBe(6);
    expect(bg.colorType).toBe(2);
  });

  test('açılış görseli 1024 şeffaf PNG; favicon ve apple-touch-icon doğru boyutta', () => {
    const splash = png('assets/splash-icon.png');
    expect([splash.width, splash.height, splash.colorType]).toEqual([1024, 1024, 6]);
    const fav = png('assets/favicon.png');
    expect([fav.width, fav.height]).toEqual([256, 256]);
    expect([fav.width, fav.height]).not.toEqual([EXPO_TEMPLATE_FAVICON_48.width, EXPO_TEMPLATE_FAVICON_48.height]);
    const touch = png('public/apple-touch-icon.png');
    expect([touch.width, touch.height, touch.colorType]).toEqual([180, 180, 2]);
    const svg = readFileSync(join(ROOT, 'public/favicon.svg'), 'utf8');
    expect(svg).toMatch(/^<svg xmlns="http:\/\/www\.w3\.org\/2000\/svg"/);
    // The SKOR SPOR mark (Logo.tsx geometry) in brand colors.
    for (const part of ['M17 37 L25 11 L32 11 L24 37 Z', '#FF7138', '#D6B77A', '#073C38']) expect(svg).toContain(part);
  });

  test('app.json yalnızca var olan marka görsellerine işaret eder; marka renkleri korunur', () => {
    const app = JSON.parse(readFileSync(join(ROOT, 'app.json'), 'utf8')).expo;
    const splash = app.plugins.find((p: unknown) => Array.isArray(p) && p[0] === 'expo-splash-screen')[1];
    const files = [
      app.icon,
      app.ios.icon.light,
      app.ios.icon.dark,
      app.ios.icon.tinted,
      app.android.adaptiveIcon.foregroundImage,
      app.android.adaptiveIcon.backgroundImage,
      app.android.adaptiveIcon.monochromeImage,
      app.web.favicon,
      splash.image,
    ];
    for (const f of files) expect(existsSync(join(ROOT, f)), f).toBe(true);
    expect(app.android.adaptiveIcon.backgroundColor).toBe('#073C38');
    expect(splash.backgroundColor).toBe('#080D0D');
  });

  test('web sayfası vektör favicon ve iOS ana ekran ikonunu bağlar; dosyalar derlemede var', () => {
    const html = readFileSync(join(ROOT, 'dist/index.html'), 'utf8');
    expect(html).toContain('<link rel="icon" type="image/svg+xml" href="/favicon.svg" />');
    expect(html).toContain('<link rel="apple-touch-icon" href="/apple-touch-icon.png" />');
    for (const f of ['favicon.svg', 'apple-touch-icon.png', 'favicon.ico']) expect(existsSync(join(ROOT, 'dist', f)), f).toBe(true);
  });
});
